content:
- [Epics]
{{~ epics = items | where 'logical_type == "Epic"' ~}}
{{~ if (epics | size) > 0 ~}}{{~ for item in epics ~}}- {{ item.id }}: {{ item.title }} (State: {{ item.state }}, Assigned to: {{ item.assigned_to }})
{{~ end ~}}{{~ else ~}}- No Epics
{{~ end ~}}

- [Features]
{{~ features = items | where 'logical_type == "Feature"' ~}}
{{~ if (features | size) > 0 ~}}{{~ for item in features ~}}- {{ item.id }}: {{ item.title }} (State: {{ item.state }}, Assigned to: {{ item.assigned_to }})
{{~ end ~}}{{~ else ~}}- No Features
{{~ end ~}}

- [Bugs]
{{~ bugs = items | where 'logical_type == "Bug"' ~}}
{{~ if (bugs | size) > 0 ~}}{{~ for item in bugs ~}}- {{ item.id }}: {{ item.title }} (State: {{ item.state }}, Assigned to: {{ item.assigned_to }})
{{~ end ~}}{{~ else ~}}- No Bugs
{{~ end ~}}
